using System.Globalization;using System.Text;using Finora.Application;using Microsoft.EntityFrameworkCore;namespace Finora.Infrastructure;public sealed class ExportService(IDbContextFactory<FinoraDbContext> factory):IExportService{public async Task<string>ExportTransactionsCsvAsync(IReadOnlyCollection<Guid>? ids=null,CancellationToken c=default){await using var db=await factory.CreateDbContextAsync(c);var q=db.Transactions.AsNoTracking().Include(x=>x.Account).Include(x=>x.Category).Where(x=>!x.IsDeleted);if(ids is{Count:>0})q=q.Where(x=>ids.Contains(x.Id));var rows=await q.OrderBy(x=>x.OccurredAtUtc).ToListAsync(c);var sb=new StringBuilder("Date,Type,AmountMinor,Currency,Account,Category,Merchant,Note\r\n");foreach(var x in rows)sb.Append(Csv(x.OccurredAtUtc.ToString("O",CultureInfo.InvariantCulture))).Append(',').Append(Csv(x.Type.ToString())).Append(',').Append(x.AmountMinor).Append(',').Append(Csv(x.Currency)).Append(',').Append(Csv(x.Account?.Name)).Append(',').Append(Csv(x.Category?.Name)).Append(',').Append(Csv(x.Merchant)).Append(',').Append(Csv(x.Note)).Append("\r\n");return sb.ToString();}public async Task<byte[]>ExportTransactionsPdfAsync(IReadOnlyCollection<Guid>? ids=null,CancellationToken c=default){var csv=await ExportTransactionsCsvAsync(ids,c);var text="Finora Transaction Export\n"+csv;return SimplePdf(text);}public async Task<IReadOnlyList<CsvImportRow>>PreviewCsvAsync(Stream stream,CancellationToken c=default){using var r=new StreamReader(stream,Encoding.UTF8,true,4096,true);var list=new List<CsvImportRow>();var n=0;while(!r.EndOfStream&&list.Count<500){c.ThrowIfCancellationRequested();var line=await r.ReadLineAsync(c);n++;if(string.IsNullOrWhiteSpace(line)||(n==1&&line.Contains("Date",StringComparison.OrdinalIgnoreCase)))continue;var cells=Parse(line);var ok=cells.Count>=5&&DateTimeOffset.TryParse(cells[0],out _)&&long.TryParse(cells[2],out _);list.Add(new CsvImportRow(n,Cell(0),Cell(2),Cell(1),Cell(4),Cell(5),Cell(6),Cell(7),ok,ok?null:"Invalid date/amount columns."));string? Cell(int i)=>i<cells.Count?cells[i]:null;}return list;}private static string Csv(string? v)=>$"\"{(v??"").Replace("\"","\"\"")}\"";private static List<string>Parse(string line){var result=new List<string>();var sb=new StringBuilder();var quoted=false;for(var i=0;i<line.Length;i++){var ch=line[i];if(ch=='\"'){if(quoted&&i+1<line.Length&&line[i+1]=='\"'){sb.Append('\"');i++;}else quoted=!quoted;}else if(ch==','&&!quoted){result.Add(sb.ToString());sb.Clear();}else sb.Append(ch);}result.Add(sb.ToString());return result;}private static byte[]SimplePdf(string text){var safe=text.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)").Replace("\r","").Split('\n').Take(45).Select(x=>x.Length>100?x[..100]:x);var content="BT /F1 9 Tf 40 760 Td "+string.Join(" 0 -14 Td ",safe.Select(x=>$"({x}) Tj"))+" ET";var objs=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",$"<< /Length {Encoding.ASCII.GetByteCount(content)} >>\nstream\n{content}\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};using var ms=new MemoryStream();using var w=new StreamWriter(ms,Encoding.ASCII,1024,true){NewLine="\n"};w.WriteLine("%PDF-1.4");w.Flush();var offsets=new List<long>{0};for(var i=0;i<objs.Length;i++){offsets.Add(ms.Position);w.WriteLine($"{i+1} 0 obj\n{objs[i]}\nendobj");w.Flush();}var xref=ms.Position;w.WriteLine($"xref\n0 {objs.Length+1}\n0000000000 65535 f ");foreach(var o in offsets.Skip(1))w.WriteLine($"{o:0000000000} 00000 n ");w.WriteLine($"trailer\n<< /Size {objs.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");w.Flush();return ms.ToArray();}}
